"""
FireRedASR2-AED offline ASR (FireRedTeam).

Catalog: firered-asr2-aed — Mandarin + 20+ Chinese dialects/accents, English,
code-switching; word-level timestamps + utterance confidence.

Long media is windowed; cues are packed from AED token timestamps (fallback:
sentence/length distribution). Language is model-auto (no explicit tag API).
"""

from __future__ import annotations

import logging
import re
import shutil
import tempfile
import threading
from pathlib import Path
from typing import Any, Callable

from ..download import is_model_installed, model_local_path
from ..progress import asr_local_from_timeline, format_mmss

ProgressCb = Callable[[dict[str, Any]], None]
CueCb = Callable[[dict[str, Any]], None]
_log = logging.getLogger("transub_engine.asr.firered_asr2")

_MODEL_CACHE: dict[str, Any] = {}
_MODEL_LOCK = threading.Lock()

_WINDOW_S = 30.0
_OVERLAP_S = 0.75
_MAX_CUE_S = 8.0
_TARGET_CUE_CHARS = 28
_GAP_BREAK_S = 0.4
_SENTENCE_END = set("。！？!?．.｡…")
_SENTENCE_SPLIT_RE = re.compile(r"(?<=[。！？!?．.｡…])")
_CJK_RE = re.compile(r"[\u3400-\u9fff\u3040-\u30ff\uac00-\ud7af]")

_WEIGHT_NAMES = ("model.pth.tar",)
_SIDECAR_NAMES = ("cmvn.ark", "dict.txt", "train_bpe1000.model")


def clear_model_cache() -> int:
    with _MODEL_LOCK:
        n = len(_MODEL_CACHE)
        _MODEL_CACHE.clear()
    try:
        import gc

        gc.collect()
    except Exception:
        pass
    try:
        import torch

        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    except Exception:
        pass
    return n


def _is_cjk(text: str) -> bool:
    return bool(_CJK_RE.search(str(text or "")))


def _join_tokens(parts: list[str]) -> str:
    if not parts:
        return ""
    if any(_is_cjk(p) for p in parts):
        return "".join(parts)
    return " ".join(parts)


def _use_gpu(device: str) -> bool:
    d = str(device or "auto").strip().lower()
    if d in ("cpu", "none", "disabled"):
        return False
    try:
        from ..device import torch_accel_is_available

        return bool(torch_accel_is_available())
    except Exception:
        pass
    try:
        import torch
        if torch.cuda.is_available() and d in ("auto", "cuda", "gpu", "amd", "rocm"):
            return True
        xpu = getattr(torch, "xpu", None)
        if xpu is not None and xpu.is_available() and d in ("auto", "cuda", "gpu", "xpu", "intel"):
            return True
    except Exception:
        return False
    return False


def _resolve_aed_dir(model_dir: Path) -> Path:
    """Accept flat Hub layout or a nested FireRedASR2-AED folder."""
    if (model_dir / "model.pth.tar").is_file() and (model_dir / "cmvn.ark").is_file():
        return model_dir
    nested = model_dir / "FireRedASR2-AED"
    if (nested / "model.pth.tar").is_file() and (nested / "cmvn.ark").is_file():
        return nested
    return model_dir


def _missing_weight_files(asr_dir: Path) -> list[str]:
    missing: list[str] = []
    for name in _WEIGHT_NAMES + _SIDECAR_NAMES:
        p = asr_dir / name
        try:
            if not p.is_file() or p.stat().st_size < 64:
                missing.append(name)
        except OSError:
            missing.append(name)
    return missing


def _get_asr_model(asr_dir: Path, device: str) -> Any:
    from fireredasr2s.fireredasr2 import FireRedAsr2, FireRedAsr2Config

    use_gpu = _use_gpu(device)
    key = f"{asr_dir}|gpu={int(use_gpu)}"
    with _MODEL_LOCK:
        cached = _MODEL_CACHE.get(key)
        if cached is not None:
            return cached
        cfg = FireRedAsr2Config(
            use_gpu=use_gpu,
            use_half=bool(use_gpu),
            beam_size=3,
            nbest=1,
            return_timestamp=True,
        )
        model = FireRedAsr2.from_pretrained("aed", str(asr_dir), cfg)
        _MODEL_CACHE[key] = model
        return model


def _probe_duration_s(media_path: str) -> float:
    try:
        from .whisper_fw import _probe_duration_s as probe

        return float(probe(media_path) or 0)
    except Exception:
        return 0.0


def _windows(duration_s: float) -> list[tuple[float, float]]:
    if duration_s <= _WINDOW_S + 1.0:
        return [(0.0, max(duration_s, 0.1))]
    out: list[tuple[float, float]] = []
    cursor = 0.0
    step = max(8.0, _WINDOW_S - _OVERLAP_S)
    while cursor < duration_s - 0.05:
        end = min(duration_s, cursor + _WINDOW_S)
        out.append((cursor, end))
        if end >= duration_s - 0.05:
            break
        cursor += step
    return out or [(0.0, max(duration_s, 0.1))]


def _split_sentences(text: str) -> list[str]:
    raw = str(text or "").strip()
    if not raw:
        return []
    parts = [p.strip() for p in _SENTENCE_SPLIT_RE.split(raw) if p and p.strip()]
    if len(parts) <= 1 and len(raw) > _TARGET_CUE_CHARS * 2:
        chunk = _TARGET_CUE_CHARS
        parts = [raw[i : i + chunk].strip() for i in range(0, len(raw), chunk)]
        parts = [p for p in parts if p]
    return parts or [raw]


def _distribute_text_cues(
    text: str,
    *,
    start: float,
    end: float,
) -> list[dict[str, Any]]:
    parts = _split_sentences(text)
    if not parts:
        return []
    span = max(0.35, float(end) - float(start))
    weights = [max(1, len(p)) for p in parts]
    total_w = float(sum(weights))
    cues: list[dict[str, Any]] = []
    cursor = float(start)
    for i, (part, w) in enumerate(zip(parts, weights)):
        frac = w / total_w
        dur = span * frac
        if i == len(parts) - 1:
            cue_end = float(end)
        else:
            cue_end = min(float(end), cursor + max(0.35, dur))
        cue_end = max(cue_end, cursor + 0.25)
        cues.append(
            {
                "start": cursor,
                "end": min(cue_end, cursor + _MAX_CUE_S * 2),
                "text": part,
            }
        )
        cursor = cue_end
    return cues


def _pack_word_cues(
    items: list[tuple[float, float, str]],
) -> list[dict[str, Any]]:
    if not items:
        return []
    cues: list[dict[str, Any]] = []
    buf: list[str] = []
    buf_start = items[0][0]
    prev_end = items[0][1]
    for start, end, text in items:
        gap = start - prev_end
        flush = False
        if buf and gap >= _GAP_BREAK_S:
            flush = True
        joined = _join_tokens(buf)
        if buf and len(joined) >= _TARGET_CUE_CHARS:
            flush = True
        if buf and joined and joined[-1] in _SENTENCE_END:
            flush = True
        if flush:
            cues.append(
                {
                    "start": buf_start,
                    "end": max(prev_end, buf_start + 0.25),
                    "text": joined.strip(),
                }
            )
            buf = []
            buf_start = start
        buf.append(text)
        prev_end = max(prev_end, end)
    if buf:
        cues.append(
            {
                "start": buf_start,
                "end": max(prev_end, buf_start + 0.25),
                "text": _join_tokens(buf).strip(),
            }
        )
    return [c for c in cues if str(c.get("text") or "").strip()]


def _normalize_timestamp_items(raw: Any) -> list[tuple[float, float, str]]:
    """Accept FireRed list/tuple rows: (token, start, end) or [token, start, end]."""
    out: list[tuple[float, float, str]] = []
    if not isinstance(raw, (list, tuple)):
        return out
    for row in raw:
        token = ""
        start = end = None
        if isinstance(row, (list, tuple)) and len(row) >= 3:
            token = str(row[0] or "").strip()
            try:
                start = float(row[1])
                end = float(row[2])
            except (TypeError, ValueError):
                continue
        elif isinstance(row, dict):
            token = str(row.get("text") or row.get("token") or row.get("word") or "").strip()
            try:
                start = float(row.get("start"))
                end = float(row.get("end", start))
            except (TypeError, ValueError):
                continue
        else:
            continue
        if not token or start is None:
            continue
        out.append((float(start), max(float(end if end is not None else start), float(start)), token))
    return out


def _result_to_cues(result: dict[str, Any], *, offset_s: float, span_s: float) -> list[dict[str, Any]]:
    conf_raw = result.get("confidence")
    try:
        confidence = float(conf_raw) if conf_raw is not None else None
    except (TypeError, ValueError):
        confidence = None

    stamps = _normalize_timestamp_items(result.get("timestamp"))
    if stamps:
        shifted = [(offset_s + s, offset_s + e, t) for s, e, t in stamps]
        cues = _pack_word_cues(shifted)
        if cues:
            if confidence is not None:
                for cue in cues:
                    cue["confidence"] = confidence
            return cues

    text = str(result.get("text") or "").strip()
    if not text:
        return []
    cues = _distribute_text_cues(
        text,
        start=offset_s,
        end=offset_s + max(0.5, float(span_s) * 0.95),
    )
    if confidence is not None:
        for cue in cues:
            cue["confidence"] = confidence
    return cues


def _transcribe_window(model: Any, wav_path: str, uttid: str) -> dict[str, Any]:
    results = model.transcribe([uttid], [wav_path])
    if isinstance(results, list) and results:
        row = results[0]
        return row if isinstance(row, dict) else {"text": str(row or "")}
    if isinstance(results, dict):
        return results
    return {"text": ""}


def firered_asr2_transcribe(
    *,
    media_path: str,
    language: str = "auto",
    asr_model: str = "firered-asr2-aed",
    device: str = "auto",
    on_progress: ProgressCb | None = None,
    on_cue: CueCb | None = None,
    should_cancel: Callable[[], bool] | None = None,
) -> list[dict[str, Any]]:
    from ..runtime_extras import ensure_extras_for_models

    _ = language  # AED has no language-tag API; dialect/EN/code-switch are model-auto.
    ensure_extras_for_models([asr_model], force=False, on_progress=on_progress)
    if not is_model_installed(asr_model):
        asr_dir = _resolve_aed_dir(model_local_path(asr_model))
        missing = _missing_weight_files(asr_dir)
        hint = f"缺少文件: {', '.join(missing)}。" if missing else ""
        raise RuntimeError(
            f"ASR model not installed or incomplete: {asr_model}. {hint}"
            "请在模型列表下载 FireRedASR2-AED（约 4.7GB）。"
        )
    asr_dir = _resolve_aed_dir(model_local_path(asr_model))
    missing = _missing_weight_files(asr_dir)
    if missing:
        raise RuntimeError(
            f"ASR model incomplete: {asr_model}（{asr_dir}）。缺少: {', '.join(missing)}。"
            "请强制重新下载。"
        )

    if on_progress:
        on_progress(
            {
                "stage": "model",
                "percent": 8,
                "detail": "加载 FireRedASR2-AED…",
            }
        )
    try:
        model = _get_asr_model(asr_dir, device)
    except ImportError as err:
        raise RuntimeError(
            "FireRedASR2-AED 需要 fireredasr2s 推理包。"
            "请重新下载该模型依赖，或在引擎 runtime 执行："
            "pip install --no-deps --find-links=wheels fireredasr2s==0.0.1。"
            f" 原始错误: {err}"
        ) from err

    duration_s = _probe_duration_s(media_path)
    if duration_s <= 0:
        raise RuntimeError(
            f"无法读取媒体时长（{media_path}），FireRedASR2 不能安全开窗。"
            "请确认 ffmpeg/ffprobe 可用后重试。"
        )
    windows = _windows(duration_s)

    from ..audio.preprocess import stage_media_for_long_asr, touch_path, trim_media_window

    work = Path(tempfile.mkdtemp(prefix="firered_asr2_"))
    all_cues: list[dict[str, Any]] = []
    fail_count = 0
    try:
        staged = stage_media_for_long_asr(media_path, work)
        for i, (start, end) in enumerate(windows):
            if should_cancel and should_cancel():
                raise RuntimeError("cancelled")
            if on_progress:
                local = asr_local_from_timeline(
                    processed_s=start,
                    duration_s=duration_s,
                    start=12.0,
                    end=92.0,
                )
                detail = f"{format_mmss(start)} / {format_mmss(duration_s)} · FireRedASR2"
                on_progress(
                    {
                        "stage": "transcribe",
                        "percent": int(local),
                        "detail": detail,
                        "processedSec": float(start),
                        "mediaDurationSec": duration_s,
                    }
                )
            if i % 10 == 0:
                touch_path(staged)
            try:
                wav = trim_media_window(
                    staged,
                    start_sec=start,
                    end_sec=end,
                    out_dir=work / f"w{i:04d}",
                )
            except Exception as err:
                fail_count += 1
                _log.warning("FireRedASR2 trim %s-%s failed: %s", start, end, err)
                if "不存在" in str(err) or "No such file" in str(err):
                    raise RuntimeError(
                        f"长片转写中途丢失输入音频（{staged}）。"
                        "请关闭对 temp/engine-work 的自动清理后重试。"
                        f" 详情: {err}"
                    ) from err
                continue
            try:
                result = _transcribe_window(model, str(wav), f"w{i:04d}")
            except Exception as err:
                fail_count += 1
                _log.warning("FireRedASR2 window %s-%s failed: %s", start, end, err)
                continue
            part = _result_to_cues(
                result,
                offset_s=start,
                span_s=max(0.1, end - start),
            )
            for cue in part:
                if on_cue:
                    on_cue(cue)
                all_cues.append(cue)
    finally:
        shutil.rmtree(work, ignore_errors=True)

    n_win = max(1, len(windows))
    if fail_count and (fail_count >= (n_win + 1) // 2 or not all_cues):
        raise RuntimeError(
            f"FireRedASR2 failed {fail_count}/{n_win} windows "
            f"({Path(media_path).name}); aborting partial transcript"
        )

    all_cues.sort(key=lambda c: (float(c.get("start") or 0), float(c.get("end") or 0)))
    cleaned: list[dict[str, Any]] = []
    for cue in all_cues:
        text = str(cue.get("text") or "").strip()
        if not text:
            continue
        item = dict(cue)
        if cleaned and float(item["start"]) < float(cleaned[-1]["end"]) - 0.05:
            item["start"] = float(cleaned[-1]["end"])
            if float(item["end"]) <= float(item["start"]):
                item["end"] = float(item["start"]) + 0.25
        cleaned.append(item)

    if on_progress:
        on_progress(
            {
                "stage": "transcribe",
                "percent": 96,
                "detail": f"{len(cleaned)} 条（FireRedASR2-AED · {int(_WINDOW_S)}s 窗）",
                "processedSec": duration_s,
                "mediaDurationSec": duration_s,
            }
        )
    return cleaned
